import unittest, json, sys
sys.path.insert(0, ".")
from components.margin_constraints.work import compute

class TestMargin(unittest.TestCase):
    def test_public(self):
        payload = json.load(open("components/margin_constraints/input.json"))
        got = compute(payload)
        self.assertEqual(got, [[True,[1,1,1,1]],[True,[1,1,1,1]]])
    def test_incompatible(self):
        payload = {"snapshots":[{"ab":[[2,0],[0,0]],"bc":[[0,0],[0,0]],"ac":[[1,0],[0,0]],"forbidden":[]}]}
        got = compute(payload)
        self.assertEqual(got, [[False,[1,0,0,0]]])
    def test_quota_rowmajor(self):
        payload = {"snapshots":[{"ab":[[1,2],[3,4]],"bc":[[0,0],[0,0]],"ac":[[1,2],[3,4]],"forbidden":[]}]}
        got = compute(payload)
        self.assertEqual(got, [[True,[1,2,3,4]]])

if __name__ == "__main__":
    unittest.main()
