import json
import sys
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT))

from components.layer_candidates.work import compute


class TestLayerCandidates(unittest.TestCase):
    def test_public_example(self):
        payload = json.loads(
            (ROOT / "components/layer_candidates/input.json").read_text(encoding="utf-8")
        )
        expected = json.loads(
            (ROOT / "components/layer_candidates/expected.json").read_text(encoding="utf-8")
        )
        self.assertEqual(compute(payload), expected)

    def test_single_cell_k2(self):
        # One customer rated (0,0,0): median 0 -> net -1.
        payload = {
            "snapshots": [{
                "ab": [[1, 0], [0, 0]],
                "bc": [[1, 0], [0, 0]],
                "ac": [[1, 0], [0, 0]],
                "forbidden": [],
            }]
        }
        result = compute(payload)
        self.assertEqual(len(result), 1)
        self.assertEqual(len(result[0]), 2)  # two b layers
        # b=0 layer has the single cell (a=0,c=0) with score -1
        self.assertEqual(result[0][0], [[[1, 0, 0, 0], -1]])
        # b=1 layer is empty
        self.assertEqual(result[0][1], [])

    def test_forbidden_removes_candidate(self):
        # Same single customer but forbid (0,0,0): no valid table.
        payload = {
            "snapshots": [{
                "ab": [[1, 0], [0, 0]],
                "bc": [[1, 0], [0, 0]],
                "ac": [[1, 0], [0, 0]],
                "forbidden": [[0, 0, 0]],
            }]
        }
        result = compute(payload)
        self.assertEqual(result[0][0], [])


if __name__ == "__main__":
    unittest.main()

